nta.declaration:
// Place global declarations here.


/************************************************************
 *                     MAP CONSTANTS
 ************************************************************/

const int WIDTH  = 18;
const int HEIGHT = 13;

const int MAX_LIVES = 5;
const int NUM_HOME_BAYS = 5;

const int INITIAL_TIME_LIMIT = 300;   // 30 s

const int MAX_PER_ROW = 4;
const int NUM_ROAD_ROWS = 5;

const int BORDER_DELAY = 2;

/************************************************************
 *                    ENUMERATIONS
 ************************************************************/

typedef int[0,3] TileType;

const TileType SAFE  = 0;
const TileType ROAD  = 1;
const TileType RIVER = 2;
const TileType HOME  = 3;

typedef int[0,4] ObjectType;

const ObjectType VEHICLE        = 0;
const ObjectType TRUCK          = 1;
const ObjectType LOG            = 2;
const ObjectType TURTLE         = 3;
const ObjectType DIVING_TURTLE  = 4;

/************************************************************
 *              IMMUTABLE OBJECT DESCRIPTION
 ************************************************************/


typedef struct
{
    int row;                    // y coordinate

    int size;                   // vehicle length

    int speed;                  // movement period

    bool moveLeft;

    ObjectType type;

    int numObjects;

    int initialX[MAX_PER_ROW];
} RowInfo;


/************************************************************
 *              MUTABLE OBJECT STATE
 ************************************************************/

typedef struct
{
    int x[MAX_PER_ROW];
} RowState;

/************************************************************
 *                GAME STATE VARIABLES
 ************************************************************/

int frog_x = 9;
int frog_y = 0;

int score = 0;
int lives = MAX_LIVES;

bool bayOccupied[NUM_HOME_BAYS] =
{
    false,false,false,false,false
};

clock levelClock; //only for the game time out

/************************************************************
 *                 STATIC MAP
 ************************************************************/

const TileType map[HEIGHT] =
{
    SAFE,   // 0
    ROAD,   // 1
    ROAD,   // 2
    ROAD,   // 3
    ROAD,   // 4
    ROAD,   // 5
    SAFE,   // 6
    RIVER,  // 7
    RIVER,  // 8
    RIVER,  // 9
    RIVER,  //10
    RIVER,  //11
    HOME    //12
};

/************************************************************
 *              SYNCHRONIZATION CHANNELS
 ************************************************************/

chan moveHop;

broadcast chan frogDies;
broadcast chan reachBay;

broadcast chan finishLevel;

/************************************************************
 *            OBJECT DECLARATIONS
 ************************************************************/
const RowInfo rowInfo[NUM_ROAD_ROWS] =
{
    //row,size,speed,left,type,numObj,{positions}

    {1,1,3,true ,VEHICLE,2,{4,14,0,0}},

    {2,1,10,false,VEHICLE,2,{2,11,0,0}},

    {3,1,5,true ,VEHICLE,4,{4,8,13,17}},

    {4,1,4,false,VEHICLE,2,{2,10,0,0}},

    {5,2,7,true ,TRUCK,2,{4,15,0,0}}
};

RowState rowState[NUM_ROAD_ROWS];

void initializeRows()
{
    int r,c;

    for(r=0;r<NUM_ROAD_ROWS;r++)
    {
        for(c=0;c<rowInfo[r].numCars;c++)
        {
            rowState[r].x[c]=rowInfo[r].initialX[c];
        }
    }
}

//shift all the objects in the row simultaneously 
void moveRow(int r)
{
    int c;

    for(c = 0; c < rowInfo[r].numCars; c++)
    {
        if(rowInfo[r].moveLeft)
        {
            rowState[r].x[c]--;

            if (rowState[r].x[c] == -(owInfo[r].size )
                rowState[r].x[c] = WIDTH + BORDER_DELAY - 1;
        }
        else
        {
            rowState[r].x[c]++;

            if (rowState[r].x[c] == WIDTH 
                rowState[r].x[c] = -(rowInfo[r].size + BORDER_DELAY - 1);
        }
    }
}

